  var json = JSON.stringify(cfg);
  if (json.length > 45000) return { success: false, error: 'Form ka config bahut bada ho gaya (category / batch list chhoti karein)' };
  writeConfigKey_('admCfg', json);
  var banner = String(body.idBanner || '');
