    h += '<svg class="sc-bg" viewBox="0 0 255 404"><defs>' +
      '<linearGradient id="gold' + u + '" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="' + T.g1 + '"/><stop offset=".5" stop-color="' + T.g2 + '"/><stop offset="1" stop-color="' + T.g1 + '"/></linearGradient>' +
      '<radialGradient id="smoke' + u + '" gradientUnits="userSpaceOnUse" cx="218" cy="190" r="88"><stop offset="0" stop-color="#2b2b2b" stop-opacity=".35"/><stop offset=".55" stop-color="#6e6e6e" stop-opacity=".18"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/></radialGradient>' +
      '</defs><rect width="255" height="404" fill="#fff"/>' +
      '<rect x="100" y="100" width="155" height="200" fill="url(#smoke' + u + ')"/>' +
      '<path d="M0,0 H255 V107 L218,115 H44 L0,93 Z" fill="' + T.dark + '"/>' +
      '<path d="M0,93 L44,115" stroke="url(#gold' + u + ')" stroke-width="2.6" fill="none"/>' +
      '<path d="M0,99 L38,118" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>' +
      '<path d="M255,107 L218,115" stroke="url(#gold' + u + ')" stroke-width="2.6" fill="none"/>' +
      '<path d="M255,112 L222,119" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>';
    if (s.title) {
      h += '<path d="M40,115 L49,104 H213 L222,115 L213,125.5 H49 Z" fill="url(#gold' + u + ')"/>' +
        '<path d="M49,104 H213 M49,125.5 H213" stroke="' + T.deep + '" stroke-width=".8" fill="none"/>' +
        '<text x="59" y="120.7" font-family="Arial,Helvetica,sans-serif" font-weight="900" font-size="14" fill="#1a1a1a" textLength="146" lengthAdjust="spacingAndGlyphs">' + esc(s.title.toUpperCase()) + '</text>';
    }
    h += '<path d="M0,336 L0,404 H68 Z" fill="' + T.dark + '"/>' +
      '<path d="M0,340 L76,404" stroke="url(#gold' + u + ')" stroke-width="3" fill="none"/>' +
      '<path d="M0,347 L58,396" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>' +
      '<path d="M255,344 L255,404 H150 Z" fill="' + T.dark + '"/>' +
      '<path d="M255,342 L146,404" stroke="url(#gold' + u + ')" stroke-width="3" fill="none"/>' +
      '<path d="M255,349 L160,404" stroke="' + T.a1 + '" stroke-width="1" fill="none"/>' +
      '</svg>';
    if (s.showDancer && assets.dancer) h += '<img class="sc-dancer f" alt="" src="' + esc(assets.dancer) + '">';
    h += '<img class="sc-banner" alt="" src="' + esc(assets.banner || BLANK) + '">';
    h += '<div class="sc-slot"></div>';
    if (s.showPhoto) h += '<div class="sc-abs sc-photo" style="border-color:' + T.a1 + '"><img alt="student photo" src="' + esc(assets.photo || BLANK) + '"></div>';
    var nameTop = s.showPhoto ? 239 : 135;
    h += '<div class="sc-abs sc-name" style="top:' + nameTop + 'px">' + esc(String((data && data.name) || '').toUpperCase()) + '</div>';
